SELECT count(*) FROM proc_po_lines AS t WHERE (t.unit IS DISTINCT FROM CASE lower(btrim(t.unit)) WHEN 'mtr' THEN 'mtr' WHEN 'set' THEN 'set' WHEN 'ltr' THEN 'ltr' WHEN 'roll' THEN 'roll' WHEN 'pair' THEN 'pair' WHEN 'pcs' THEN 'pcs' WHEN 'kg' THEN 'kg' WHEN 'nos.' THEN 'pcs' WHEN 'nos' THEN 'pcs' WHEN 'no.' THEN 'pcs' WHEN 'no' THEN 'pcs' WHEN 'unit' THEN 'pcs' WHEN 'units' THEN 'pcs' WHEN 'pc' THEN 'pcs' WHEN 'piece' THEN 'pcs' WHEN 'pieces' THEN 'pcs' WHEN 'kgs' THEN 'kg' WHEN 'kilogram' THEN 'kg' WHEN 'sets' THEN 'set' WHEN 'ltrs' THEN 'ltr' WHEN 'litre' THEN 'ltr' WHEN 'liter' THEN 'ltr' WHEN 'mtrs' THEN 'mtr' WHEN 'meter' THEN 'mtr' WHEN 'metre' THEN 'mtr' WHEN 'm' THEN 'mtr' WHEN 'pairs' THEN 'pair' WHEN 'rolls' THEN 'roll' ELSE t.unit END);
